1	//! The config file the front ends share.
2	//!
3	//! One `key = value` per line: greppable, hand-editable, no parser dependency.
4	//! Anything unrecognised is kept as it was rather than dropped, so the TUI
5	//! writing its theme cannot delete the GUI's settings and vice versa — the
6	//! whole reason this is a shared type rather than a `fs::write` in each.
7	
8	use std::fs;
9	use std::path::{Path, PathBuf};
10	
11	use anyhow::Result;
12	
13	/// The file as a list of key/value pairs, in the order they were read.
14	#[derive(Clone, Debug, Default, PartialEq, Eq)]
15	pub struct Config {
16	    entries: Vec<(String, String)>,
17	}
18	
19	impl Config {
20	    pub fn load() -> Config {
21	        match path() {
22	            Some(path) => Config::load_from(&path),
23	            None => Config::default(),
24	        }
25	    }
26	
27	    /// A missing or unreadable file is an empty config, never an error: a
28	    /// broken config should not stop you seeing the board.
29	    pub fn load_from(path: &Path) -> Config {
30	        let Ok(text) = fs::read_to_string(path) else {
31	            return Config::default();
32	        };
33	        let mut entries = Vec::new();
34	        for line in text.lines() {
35	            let line = line.trim();
36	            if line.is_empty() || line.starts_with('#') {
37	                continue;
38	            }
39	            if let Some((key, value)) = line.split_once('=') {
40	                entries.push((key.trim().to_string(), value.trim().to_string()));
41	            }
42	        }
43	        Config { entries }
44	    }
45	
46	    pub fn get(&self, key: &str) -> Option<&str> {
47	        self.entries
48	            .iter()
49	            .find(|(name, _)| name == key)
50	            .map(|(_, value)| value.as_str())
51	    }
52	
53	    /// Set a key, keeping its position if it was already there so the file
54	    /// doesn't reshuffle every time it's written.
55	    pub fn set(&mut self, key: &str, value: &str) {
56	        match self.entries.iter_mut().find(|(name, _)| name == key) {
57	            Some((_, existing)) => *existing = value.to_string(),
58	            None => self.entries.push((key.to_string(), value.to_string())),
59	        }
60	    }
61	
62	    pub fn save(&self) -> Result<()> {
63	        let path = path().ok_or_else(|| anyhow::anyhow!("no config directory"))?;
64	        self.save_to(&path)
65	    }
66	
67	    pub fn save_to(&self, path: &Path) -> Result<()> {
68	        if let Some(parent) = path.parent() {
69	            fs::create_dir_all(parent)?;
70	        }
71	        let mut text = String::new();
72	        for (key, value) in &self.entries {
73	            text.push_str(&format!("{key} = {value}\n"));
74	        }
75	        fs::write(path, text)?;
76	        Ok(())
77	    }
78	}
79	
80	/// `$XDG_CONFIG_HOME/agile-md/config`, else `~/.config/agile-md/config`.
81	pub fn path() -> Option<PathBuf> {
82	    let base = std::env::var_os("XDG_CONFIG_HOME")
83	        .map(PathBuf::from)
84	        .or_else(|| std::env::var_os("HOME").map(|home| PathBuf::from(home).join(".config")))?;
85	    Some(base.join("agile-md").join("config"))
86	}
87	
88	#[cfg(test)]
89	mod tests {
90	    use super::*;
91	
92	    #[test]
93	    fn a_missing_file_is_an_empty_config() {
94	        let dir = tempfile::tempdir().unwrap();
95	        let config = Config::load_from(&dir.path().join("nope"));
96	        assert_eq!(config, Config::default());
97	        assert_eq!(config.get("anything"), None);
98	    }
99	
100	    #[test]
101	    fn writing_one_key_keeps_the_others() {
102	        let dir = tempfile::tempdir().unwrap();
103	        let path = dir.path().join("config");
104	        fs::write(&path, "theme = nord\ngui.font = large\n").unwrap();
105	
106	        // The TUI saving its theme must not delete the GUI's settings.
107	        let mut config = Config::load_from(&path);
