    /// the board.
    pub fn tasks_in_group(&self, name: &str) -> Result<Vec<Task>> {
        Ok(self
            .tasks()?
            .into_iter()
            .filter(|task| match task.column {
                Column::Backlog => task.epic.as_deref() == Some(name),
