        task.set_points("5").unwrap();
        board.set_epic(&task, Some("sprint-1")).unwrap();
        assert_eq!(board.tasks_in_group("sprint-1").unwrap().len(), 1);

        let task = board.find("001").unwrap();
        board.move_task(&task, Column::Doing).unwrap();
        assert_eq!(
